@pytest.mark.parametrize('max_iter', [1, 18000])
def test_lbfgs_max_iter(Estimator, max_iter, monkeypatch):
    # Check limits above SciPy's default without an expensive long fit.
    from sklearn.neural_network import multilayer_perceptron

    optimizer = multilayer_perceptron.fmin_l_bfgs_b
    optimizer_kwargs = {}

    def capture_optimizer_kwargs(*args, **kwargs):
        optimizer_kwargs.update(kwargs)
        return optimizer(*args, **kwargs)

    monkeypatch.setattr(multilayer_perceptron, 'fmin_l_bfgs_b',
                        capture_optimizer_kwargs)
    mlp = Estimator(solver='lbfgs', hidden_layer_sizes=5,
                    max_iter=max_iter, random_state=0)
    mlp.fit(X_iris, y_iris)

    assert optimizer_kwargs.get('maxiter') == max_iter
    # Function evaluations and iterations have separate limits.
    assert 'maxfun' not in optimizer_kwargs


